// The ONE place that decides which glyph a UI icon name renders.
// Icon set: Material Symbols, Outlined style, weight 400, grade 0, optical size 24 (package @material-symbols/svg-400,
// Apache-2.0), the standard Material Design 3 icon set. Glyph path data is bundled (no CDN, works offline) in
// iconGlyphs.ts, which is GENERATED by `npm run gen:icons` from the Material names used in this file, so only
// the listed icons ship. To add an icon: add `ui_name: 'material_symbol_name'` below (look the name up at
// https://fonts.google.com/icons), add the glyph to FILLED when it needs a filled "selected" variant, run
// `npm run gen:icons`, and commit iconGlyphs.ts.
import { GLYPHS, type Glyph } from './iconGlyphs'

