/** Glyphs that also ship a filled variant (used by `fill`: selected navigation, status, folders). */
export const FILLED: string[] = [
  'space_dashboard', 'dashboard', 'upload_file', 'smart_toy', 'task_alt', 'folder_open', 'table_view', 'folder_managed',
  'rule_settings', 'cloud_sync', 'settings', 'group', 'shield_lock', 'devices', 'history', 'monitor_heart', 'home',
  'check_circle', 'cancel', 'error', 'warning', 'info', 'folder', 'draft', 'description', 'shield', 'database',
]

export const FALLBACK_ICON: Glyph = GLYPHS.circle

export const ICON_MAP: Record<string, Glyph> = {}
for (const [ui, name] of Object.entries(NAMES)) if (GLYPHS[name]) ICON_MAP[ui] = GLYPHS[name]

/** Names this module declares (used by scripts/gen-icons.mjs and tests). */
export const ICON_GLYPH_NAMES = NAMES

const warned = new Set<string>()

/** Resolves a UI icon name to a glyph; unknown names get the neutral fallback (and one dev-only warning). */
export function resolveIcon(name: string): Glyph {
  const c = ICON_MAP[name]
  if (c) return c
  if (import.meta.env?.DEV && !warned.has(name)) {
    warned.add(name)
    console.warn(`[Icon] "${name}" has no entry in components/iconMap.ts; using the fallback icon`)
  }
  return FALLBACK_ICON
}
